    h=obs['hitch_deg']
    v=obs.get('views',{}).get('direct')
    if v:
        ox,oy=v['origin']
        yl=None;yr=None
        for b,d in v['walls']:
            if abs(b)>120 and d<9:
                x=ox+d*math.cos(math.radians(b));y=oy+d*math.sin(math.radians(b))
                if x<-1.3 and x>-8:
                    if y>0:
                        yl=y if yl is None else min(yl,y)
                    else:
                        yr=-y if yr is None else min(yr,-y)
        if yl is not None and yr is not None:
            t=3.0*(yl-yr)
            tgt=max(-12,min(12,t))
    err=h-tgt
    st=max(-45,min(45,1.6*err))
    return (st,-0.6,180)

